//! Emoji picker: `:feu` / `:fire` lists matching emojis; Enter copies the emoji.
use super::rank::fold;
use super::{Entry, Kind};
use serde::Deserialize;
use std::sync::OnceLock;

const MAX_RESULTS: usize = 40;
const SUB_COPY: &str = "Entrée : copier";

/// Generated by `scripts/gen-emoji.mjs` (French + English keywords, no skin-tone variants).
const DATA: &str = include_str!("emoji.json");

#[derive(Deserialize)]
struct Raw {
    e: String,
    k: Vec<String>,
}

struct Emoji {
    glyph: String,
    /// First keyword as generated (the French label), shown in the title.
    label: String,
    /// All keywords, folded (lowercase, no diacritics).
    folded: Vec<String>,
}

fn fold_str(s: &str) -> String {
    s.chars().map(fold).collect()
}

fn all() -> &'static [Emoji] {
    static ALL: OnceLock<Vec<Emoji>> = OnceLock::new();
    ALL.get_or_init(|| {
        let raw: Vec<Raw> = serde_json::from_str(DATA).unwrap_or_else(|e| {
            eprintln!("lucent: cannot parse emoji data: {e}");
            Vec::new()
        });
        raw.into_iter()
            .map(|r| Emoji {
                label: r.k.first().cloned().unwrap_or_default(),
                folded: r.k.iter().map(|k| fold_str(k)).collect(),
                glyph: r.e,
            })
            .collect()
    })
}

/// Lower is better: 0 exact keyword, 1 keyword prefix, 2 word prefix, 3 substring.
fn score(keywords: &[String], needle: &str) -> Option<u8> {
    keywords
        .iter()
        .filter_map(|k| {
            if k == needle {
                Some(0)
            } else if k.starts_with(needle) {
                Some(1)
            } else if k.split(' ').any(|w| w.starts_with(needle)) {
                Some(2)
            } else if k.contains(needle) {
                Some(3)
            } else {
                None
            }
        })
        .min()
}

/// Entries for a `:text` query (empty when `q` has no `:` prefix or nothing after it).
/// The glyph travels in `keywords[0]` for the opener.
pub fn lookup(q: &str) -> Vec<Entry> {
    let Some(rest) = q.strip_prefix(':') else { return Vec::new() };
    let needle = fold_str(rest.trim());
    if needle.is_empty() {
        return Vec::new();
    }
    let mut hits: Vec<(u8, usize, usize)> = all()
        .iter()
        .enumerate()
        .filter_map(|(i, e)| score(&e.folded, &needle).map(|s| (s, e.label.chars().count(), i)))
        .collect();
    hits.sort(); // by score, then shorter label (the plain emoji before compounds), then data order
    hits.truncate(MAX_RESULTS);
    hits.into_iter()
        .map(|(_, _, i)| {
            let e = &all()[i];
            Entry {
                id: format!("emoji:{}", e.glyph),
                kind: Kind::Emoji,
                title: format!("{} {}", e.glyph, e.label),
                subtitle: SUB_COPY.into(),
                icon: None,
                keywords: vec![e.glyph.clone()],
                valo: None,
            }
        })
        .collect()
}

/// Opener (Emoji kind): copies the glyph.
pub fn open(e: &Entry, _mods: super::OpenMods) {
    if let Some(g) = e.keywords.first() {
        super::clipboard::clipboard_write(g);
    }
}

pub fn init() {
    super::register_opener(Kind::Emoji, open);
}

#[cfg(test)]
fn data_len() -> usize {
    all().len()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn glyphs(q: &str) -> Vec<String> {
        lookup(q).into_iter().map(|e| e.keywords[0].clone()).collect()
    }

    #[test]
    fn emoji_lookup_matches_french_and_english() {
        assert!(glyphs(":feu").contains(&"🔥".to_string()));
        assert!(glyphs(":fire").contains(&"🔥".to_string()));
        assert!(glyphs(":FEU").contains(&"🔥".to_string()));
        assert_eq!(glyphs(":feu")[0], "🔥", "exact keyword ranks first");
        assert!(glyphs(":bruler").contains(&"🔥".to_string()), "diacritics are folded");
        let e = &lookup(":feu")[0];
        assert_eq!(e.kind, Kind::Emoji);
        assert_eq!(e.id, "emoji:🔥");
    }

    #[test]
    fn emoji_lookup_is_capped_and_safe() {
        assert!(glyphs(":").is_empty());
        assert!(glyphs(": ").is_empty());
        assert!(glyphs(":zzzzqqqq").is_empty());
        assert!(glyphs("feu").is_empty());
        assert!(glyphs(":e").len() <= 40);
        assert_eq!(glyphs(":e").len(), 40);
        let _ = lookup(":é");
        let _ = lookup(":🔥");
    }

    #[test]
    fn emoji_data_has_no_skin_variants() {
        assert!(!glyphs(":signe de la main").iter().any(|g| g.contains('\u{1F3FB}')));
        assert!(data_len() > 1500);
    }
}
